  "explanation": "Carcinomul scuamocelular rămâne cel mai comun tip din Europa și poate cauza cavități cu necroză centrală — Corect: Carcinomul scuamocelular este cel mai comun în Europa şi poate cauza cavităţi cu necroză centrală.\n\nAdenocarcinomul este cel mai comun tip de celule la nefumători și cauzează frecvent leziuni periferice — Corect: Adenocarcinomul este cel mai comun la nefumători, cu leziuni tipic periferice.\n\nCarcinomul cu celule mici își are originea în celulele neuroendocrine și metastazează frecvent precoce — Corect: Carcinomul cu celule mici provine din celule neuroendocrine şi metastazează precoce.\n\nCarcinomul cu celule mici este clasificat ca formă de carcinom non-microcelular, alături de adenocarcinom — Incorect: Carcinomul cu celule mici este o categorie separată, nu face parte din carcinomul non-microcelular.\n\nCarcinomul cu celule mici reprezintă tipul cel mai frecvent de cancer pulmonar în Marea Britanie — Incorect: Conform tabelului, carcinomul scuamocelular (35%) este mai frecvent decât carcinomul cu celule mici (20%).\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 28, p. 976, Investigații — Tipurile de celule neoplazice pulmonare (pagini PDF: 184).",
