  "explanation": "În infecția cu Legionella: limfopenie fără leucocitoză marcată, hiponatremie, hipoalbuminemie și transaminaze crescute — Corect: Acesta este profilul de laborator descris pentru Legionella.\n\nUn test HIV trebuie oferit tuturor pacienților cu pneumonie, ca formă frecventă de debut al infecției nediagnosticate — Corect: Testul HIV este recomandat tuturor pacienților cu pneumonie.\n\nÎn infecția cu Mycoplasma, leucocitoza >15×10³/µL cu neutrofilie 90% este regula — Incorect: Leucocitoza marcată cu neutrofilie caracterizează pneumococul; în Mycoplasma numărul de leucocite este de obicei normal.\n\nAntigenul urinar Legionella înlocuiește gazometria când saturația este <94% — Incorect: Gazometria este indicată la saturație <94%, independent de antigenul urinar.\n\nHemoculturile se omit sistematic în pneumonia moderată-severă, pentru a nu întârzia antibioticul — Incorect: Hemoculturile sunt necesare în PC moderată sau severă, ideal înainte de antibiotic, fără a amâna prima doză.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 28, p. 965, Investigații — Analize de sânge; Alte teste (pagini PDF: 175).",
